  expect(loadConfig("\n  # x\n\n")).toStrictEqual({ ok: true, config: DEFAULTS });
  expect(loadConfig("# c\nversion: 2\n")).toStrictEqual({ ok: false, problems: ["version: must be 1"] });
});

test("Load Config example 6: a config that cannot be read is a DeckError result", () => {
  const r = tmpRoot("morph-p25bcfg-");
  const unreadable = (reason: string) => ({ ok: false, result: { code: 2, document: { error: { code: 2, kind: "DeckError",
    message: "morph.config.yaml cannot be read: " + reason } } } });
  try {
    fs.symlinkSync("morph.config.yaml", r.path("morph.config.yaml"));
    expect(readProjectConfig(r.root)).toStrictEqual(unreadable("ELOOP"));
    fs.rmSync(r.path("morph.config.yaml"));
    r.write("morph.config.yaml", "version: 1\n");
    fs.chmodSync(r.path("morph.config.yaml"), 0o000);
    if (process.getuid?.() !== 0) expect(readProjectConfig(r.root)).toStrictEqual(unreadable("EACCES"));
  } finally {
    if (fs.existsSync(r.path("morph.config.yaml"))) fs.chmodSync(r.path("morph.config.yaml"), 0o644);
    r.rm();
  }
});
